package com.kaymlyn.planeteater.claude;

import com.kaymlyn.planeteater.simulation.physics.Vector3D;

/**
 * Verify that Vector3D rotation methods are proper inverses
 *
 * Generated by Claude (Sonnet 4.5)
 */
public class RotationMatrixVerification {

    public static void main(String[] args) {
        System.out.println("=== ROTATION MATRIX VERIFICATION ===\n");

        // Test various angles
        double[] testAngles = {
                0.0,
                Math.PI / 6,  // 30°
                Math.PI / 4,  // 45°
                Math.PI / 3,  // 60°
                Math.PI / 2,  // 90°
                Math.PI,      // 180°
        };

        for (double omega : testAngles) {
            for (double incl : testAngles) {
                for (double w : testAngles) {
                    testRoundTrip(omega, incl, w);
                }
            }
        }

        System.out.println("\n✓ All rotation round-trip tests passed!");
    }

    private static void testRoundTrip(double omega, double incl, double w) {
        // Test 1: 2D → 3D → 2D (should work - 2D vectors stay in orbital plane)
        Vector3D vec2D = new Vector3D(1.5e11, 5e10, 0);  // z MUST be 0 for 2D

        // Rotate to 3D
        Vector3D vec3D = vec2D.rotateInto3spaceFrom2space(omega, incl, w);

        // Rotate back to 2D
        Vector3D vec2DRecovered = vec3D.rotateInto2spaceFrom3space(omega, incl, w);

        // Check if we got back to original (only x and y matter, z will be 0)
        double error = Math.sqrt(
                Math.pow(vec2D.getX() - vec2DRecovered.getX(), 2) +
                        Math.pow(vec2D.getY() - vec2DRecovered.getY(), 2)
        );

        if (error > 1e-4) {  // 1 micrometer tolerance
            System.err.printf("FAIL (2D→3D→2D): Ω=%.2f°, i=%.2f°, ω=%.2f°\n",
                    Math.toDegrees(omega),
                    Math.toDegrees(incl),
                    Math.toDegrees(w));
            System.err.println("  Original 2D: " + vec2D);
            System.err.println("  3D: " + vec3D);
            System.err.println("  Recovered 2D: " + vec2DRecovered);
            System.err.printf("  Error: %.3e m\n", error);
            throw new AssertionError("2D→3D→2D transformation failed!");
        }

        // Test 2: 3D → 2D → 3D (ONLY works for vectors IN the orbital plane)
        // We need to create a 3D vector that's already in the orbital plane
        Vector3D testVec2D = new Vector3D(1.5e11, 5e10, 0);
        Vector3D vec3DInPlane = testVec2D.rotateInto3spaceFrom2space(omega, incl, w);

        // Project to 2D
        Vector3D vec2DTemp = vec3DInPlane.rotateInto2spaceFrom3space(omega, incl, w);

        // Rotate back to 3D
        Vector3D vec3DRecovered = vec2DTemp.rotateInto3spaceFrom2space(omega, incl, w);

        // Should match the in-plane vector
        error = vec3DInPlane.subtract(vec3DRecovered).magnitude();

        if (error > 1e-4) {
            System.err.printf("FAIL (3D in-plane→2D→3D): Ω=%.2f°, i=%.2f°, ω=%.2f°\n",
                    Math.toDegrees(omega),
                    Math.toDegrees(incl),
                    Math.toDegrees(w));
            System.err.println("  Original 3D (in plane): " + vec3DInPlane);
            System.err.println("  2D: " + vec2DTemp);
            System.err.println("  Recovered 3D: " + vec3DRecovered);
            System.err.printf("  Error: %.3e m\n", error);
            throw new AssertionError("3D in-plane→2D→3D transformation failed!");
        }
    }
}
